def split_csv(line):
    fields = []
    i = 0

    while i <= len(line):
        # Determine where this field ends
        if i == len(line):
            # End of line - add the field we've been collecting
            fields.append("")
            break

        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - add one quote to field
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None

            # After closing quote, must be comma or end of line
            if i < len(line) and line[i] != ',':
                return None

            fields.append(field)

            # Move past the comma if present
            if i < len(line):
                i += 1
        else:
            # Unquoted field - runs to next comma or end of line
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field cannot contain double quotes
                    return None
                field += line[i]
                i += 1

            fields.append(field)

            # Move past the comma if present
            if i < len(line):
                i += 1

    return fields

